 return {state:()=>({version,sessionVersion,highestVersion,inspects,installs,restores,reloads,busy:view.isSaving,committing}),confirm:(v:boolean)=>confirmed=v,fail:(v:boolean)=>fail=v,pending:()=>pending=true,release:()=>{pending=false;late?.();},leave:()=>view.leave(),mount};
